arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -d "limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d.get('error'), d)
    sys.exit(1)
for u in d['members']:
    if u.get('is_bot') and 'release' in u.get('real_name','').lower():
        print(json.dumps(u, indent=2))
"

